@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + seatCount : int
  + isSmoking : boolean
}

class Reservation {
  + date : date
  + time : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + totalAmount : float
}

class Dish {
  + name : string
  + unitPrice : float
}

class BillLine {
  + quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "*" -- "1..*" Table : assignedTo
Waiter "1" -- "*" Customer : serves
Customer "1" -- "*" Bill : pays
Bill "1" *-- "*" BillLine : contains
BillLine "*" -- "1" Dish : refersTo

@enduml

